import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { LmlError } from "../../src/contracts.js";
import { loadBundle, loadDocument } from "../../src/lml/index.js";
import { BUILTIN_TYPES, RESERVED_ATTRIBUTE_NAMES } from "../../src/lml/validator.js";

// Golden cases generated by the Ruby reference (lutaml-model 72b89c5, review card R2):
// `ruby -Ilib test/lml/fixtures/r2_refusals.generator.rb <out.json>` in that worktree.
// Documents run DocumentValidator.validate!; bundles run Importer.bundle (text).
interface Golden {
  readonly name: string;
  readonly kind: "document" | "bundle";
  readonly input: string;
  readonly expect: { readonly reason: string; readonly location: string | null; readonly detail: string } | null;
}
const cases = JSON.parse(readFileSync(new URL("./fixtures/r2_refusals.json", import.meta.url), "utf8")) as Golden[];
const enc = new TextEncoder();

function run(c: Golden): LmlError | undefined {
  try {
    (c.kind === "bundle" ? loadBundle : loadDocument)(enc.encode(c.input), "json");
  } catch (error) {
    if (error instanceof LmlError) return error;
    throw error;
  }
  return undefined;
}

describe("R2 parity with the Ruby validator (golden cases)", () => {
  it("covers every reserved name, depth boundary and duplicate-key case", () => {
    expect(RESERVED_ATTRIBUTE_NAMES).toHaveLength(25);
    for (const name of RESERVED_ATTRIBUTE_NAMES) expect(cases.some((c) => c.name === `reserved_${name}`), name).toBe(true);
    expect(cases.filter((c) => c.expect === null).length).toBeGreaterThan(20);
    expect(cases.filter((c) => c.expect !== null).length).toBeGreaterThan(60);
  });

  it("pins one accepted and one refused default per builtin type", () => {
    for (const type of BUILTIN_TYPES) {
      expect(cases.find((c) => c.name === `typed_default_ok_${type}`)?.expect, type).toBeNull();
      expect(cases.find((c) => c.name === `typed_default_refused_${type}`)?.expect, type).not.toBeNull();
    }
  });

  it.each(cases.map((c) => [c.name, c] as const))("%s", (_name, c) => {
    const error = run(c);
    if (c.expect === null) {
      expect(error?.info, "accepted by Ruby, so by TS").toBeUndefined();
      return;
    }
    expect(error, "refused by Ruby, so by TS").toBeDefined();
    expect(error?.info.reason).toBe(c.expect.reason);
    // Ruby has no pointer for a text-level refusal (nil); TS reports "".
    expect(error?.info.location).toBe(c.expect.location ?? "");
    if (c.name.startsWith("doc_depth") || c.name.startsWith("dup_")) expect(error?.info.detail).toBe(c.expect.detail);
  });

  it("depth boundary: exactly 100 container levels load, 101 are refused (document and bundle text)", () => {
    const byName = new Map(cases.map((c) => [c.name, c]));
    expect(run(byName.get("doc_depth_100") as Golden)).toBeUndefined();
    expect(run(byName.get("doc_depth_101") as Golden)?.info.detail).toBe("nesting deeper than 100 levels");
    expect(run(byName.get("bundle_depth_100") as Golden)).toBeUndefined();
    expect(run(byName.get("bundle_depth_101") as Golden)?.info.reason).toBe("invalid_document");
  });

  it("legacy v1 JSON documents keep the last duplicate key (only bundle text refuses duplicates)", () => {
    const loaded = loadDocument(enc.encode('{"lml":1,"model":"A","model":"B"}'), "json");
    expect((loaded.document as { model: string }).model).toBe("B");
  });
});
